import { tv, type VariantProps } from "@/lib/beton/tv";

export const stepper = tv({
  slots: {
    root: "flex w-full",
    item: "relative flex min-w-0 flex-1 gap-3",
    marker: [
      "z-10 flex shrink-0 items-center justify-center border-3 border-border bg-raised",
      "font-display font-black text-foreground",
      "data-[state=complete]:bg-primary data-[state=current]:bg-secondary",
    ],
    content: "flex min-w-0 flex-col gap-0.5",
    title: "font-display font-extrabold text-foreground",
    description: "text-caption text-foreground",
    connector: "bg-border data-[state=complete]:bg-primary",
  },
  variants: {
    orientation: {
      horizontal: {
        root: "flex-row items-start gap-2",
        item: "flex-col items-center text-center",
        connector:
          "absolute top-(--connector-offset) right-[calc(-50%+var(--marker-half))] left-[calc(50%+var(--marker-half))] h-1",
      },
      vertical: {
        root: "flex-col gap-6",
        item: "flex-row items-start pb-6 last:pb-0",
        connector: "absolute top-(--marker-size) bottom-0 left-(--connector-offset) w-1",
      },
    },
    size: {
      sm: {
        root: "[--marker-size:2.25rem] [--marker-half:1.125rem] [--connector-offset:1rem]",
        marker: "size-9 text-sm",
        title: "text-sm",
      },
      md: {
        root: "[--marker-size:2.75rem] [--marker-half:1.375rem] [--connector-offset:1.25rem]",
        marker: "size-11 text-base",
        title: "text-base",
      },
      lg: {
        root: "[--marker-size:3.5rem] [--marker-half:1.75rem] [--connector-offset:1.625rem]",
        marker: "size-14 text-lg",
        title: "text-lg",
      },
    },
  },
  defaultVariants: {
    orientation: "horizontal",
    size: "md",
  },
});

export type StepperVariants = VariantProps<typeof stepper>;

import { stepper, type StepperVariants } from "@/lib/beton/recipes/stepper.recipe";
import { visuallyHidden } from "@/lib/beton/shared";
import {
  Children,
  cloneElement,
  isValidElement,
  type ComponentProps,
  type ReactElement,
  type ReactNode,
} from "react";
import { CheckIcon } from "@/lib/beton/icons";

export type StepState = "complete" | "current" | "upcoming";

export interface StepperProps extends Omit<ComponentProps<"ol">, "children">, StepperVariants {
  children?: ReactNode;
  /** The step being worked on, counting from 0. Earlier steps read as done. */
  activeStep?: number;
}

function StepperRoot({
  activeStep = 0,
  orientation = "horizontal",
  size = "md",
  className,
  children,
  "aria-label": ariaLabel = "Progress",
  ...props
}: StepperProps) {
  const styles = stepper({ orientation, size });
  const steps = Children.toArray(children).filter(isValidElement);
  return (
    <ol
      {...props}
      aria-label={ariaLabel}
      data-orientation={orientation}
      className={styles.root({ class: className })}
    >
      {steps.map((step, index) =>
        cloneElement(step as ReactElement<StepProps>, {
          index,
          orientation,
          size,
          state:
            (step as ReactElement<StepProps>).props.state ??
            (index < activeStep ? "complete" : index === activeStep ? "current" : "upcoming"),
          last: index === steps.length - 1,
        }),
      )}
    </ol>
  );
}

export interface StepProps extends Omit<ComponentProps<"li">, "title">, StepperVariants {
  /** The name of the step. */
  title: ReactNode;
  /** A line of detail under the title. */
  description?: ReactNode;
  /** What is shown in the marker. Defaults to the step number, or a tick once done. */
  marker?: ReactNode;
  /** Overrides what Stepper worked out from `activeStep`. */
  state?: StepState;
  /** Set by Stepper. */
  index?: number;
  /** Set by Stepper. */
  last?: boolean;
}

function Step({
  title,
  description,
  marker,
  state = "upcoming",
  index = 0,
  last = false,
  orientation = "horizontal",
  size = "md",
  className,
  children,
  ...props
}: StepProps) {
  const styles = stepper({ orientation, size });
  return (
    <li
      {...props}
      data-state={state}
      aria-current={state === "current" ? "step" : undefined}
      className={styles.item({ class: className })}
    >
      <span data-state={state} className={styles.marker()}>
        {marker ?? (state === "complete" ? <CheckIcon width={20} height={20} /> : index + 1)}
        <span className={visuallyHidden}>
          {state === "complete" ? " (done)" : state === "current" ? " (current step)" : ""}
        </span>
      </span>
      <span className={styles.content()}>
        <span className={styles.title()}>{title}</span>
        {description ? <span className={styles.description()}>{description}</span> : null}
        {children}
      </span>
      {last ? null : <span aria-hidden="true" data-state={state} className={styles.connector()} />}
    </li>
  );
}

/** Shows where someone is in a task that runs over several steps. */
export const Stepper = Object.assign(StepperRoot, { Step });
